///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fnSubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnSubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSubmit",
        method: "post",
        action: "/sales/sales.do",
        ref: "dma_fnSubmitReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf50200.tx_fnSubmit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.fnSubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSubmit = async function () {
    /* sdd-asis-lifecycle:begin fnSubmit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    if ($c.util.getComponent("ipt_perInfo1").checked === false) {
        await $c.win.alert("개인정보 처리방침에 동의해주세요.");
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return;
    }
    if ($c.util.getComponent("ipt_perInfo2").checked === false) {
        await $c.win.alert("개인정보 수집 및 이용에 동의해주세요.");
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return;
    }
    if (!await scwin.ReqDataCheckValues(fm)) {
        return;
    }
    if (await $c.win.confirm("변경하시겠습니까?")) {
        $c.util.getComponent('dma_fnSubmitReq').set('method', "modifySalesUserInfo");
        fm.action = "/sales/sales.do";
        fm.target = "_self";
        await scwin.tx_fnSubmit();
    }
    /* sdd-asis-lifecycle:end */
};


